<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { Check, CheckCircle2, Clock3, X } from 'lucide-vue-next'
import { api, dateTime, statusLabel, statusTone } from './api'
import type { Approval, Module, User } from './types'

const props = defineProps<{ user: User; modules: Module[] }>()
const emit = defineEmits<{ 'open-record': [module: string, id: string]; changed: [] }>()
const items = ref<Approval[]>([]), users = ref<User[]>([]), status = ref('pending'), error = ref(''), selected = ref<Approval>(), decision = ref('approved'), comment = ref(''), transferTo = ref(''), busy = ref(false), loading = ref(true)
async function load() { loading.value = true; try { items.value = await api<Approval[]>('/approvals?status=' + status.value); error.value = '' } catch (e) { error.value = (e as Error).message } finally { loading.value = false } }
onMounted(async () => { await load(); if (props.user.role !== 'sales') users.value = await api<User[]>('/users') })
function review(item: Approval, value: string) { selected.value = item; decision.value = value; comment.value = ''; transferTo.value = ''; error.value = '' }
async function submit() {
  if (!selected.value) return
  busy.value = true
  try { const assignment = decision.value === 'transferred' || decision.value === 'added'; await api(`/approvals/${selected.value.id}/${decision.value === 'transferred' ? 'transfer' : decision.value === 'added' ? 'add-signer' : 'decision'}`, 'POST', assignment ? { target_user_id: transferTo.value, comment: comment.value } : { decision: decision.value, comment: comment.value }); selected.value = undefined; await load(); emit('changed') }
  catch (e) { error.value = (e as Error).message }
  finally { busy.value = false }
}
</script>

<template>
    <div class="page"><header class="page-heading"><div><div class="eyebrow">TEAM COLLABORATION</div><h1>审批中心</h1><p>{{ user.role === 'sales' ? '查看业务单据的审批进度与处理意见' : '让每一笔业务流转清晰、有据可查' }}</p></div><span class="today"><CheckCircle2 :size="18"/>{{ user.role === 'sales' ? '我的业务审批' : '按流程角色处理审批' }}</span></header><p v-if="error && !selected" class="error-banner">{{ error }}</p><section class="panel data-panel"><div class="table-tabs"><div><button v-for="s in [{ key: 'pending', label: '待审批' }, { key: 'approved', label: '已通过' }, { key: 'rejected', label: '已驳回' }, { key: 'withdrawn', label: '已撤回' }, { key: '', label: '全部记录' }]" :key="s.key" :class="{ active: status === s.key }" @click="status = s.key; load()">{{ s.label }}</button></div><span class="tiny-label">{{ items.length }} 条</span></div><div v-if="loading" class="loading-state">加载审批记录…</div><div v-else-if="!items.length" class="empty table-empty"><CheckCircle2 :size="38"/><h3>暂无{{ statusLabel[status] || '' }}记录</h3><p>在报价、合同、订单、发票或回款详情中提交审批。</p></div><div v-else class="table-scroll"><table><thead><tr><th>业务单据</th><th>所属模块</th><th>提交人</th><th>提交时间</th><th>状态</th><th>处理人 / 意见</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><button class="reference-link" @click="emit('open-record', item.module, item.record_id)">{{ item.name }}</button></td><td>{{ modules.find(m => m.key === item.module)?.label }}</td><td>{{ item.requester_name }}</td><td>{{ dateTime(item.created_at) }}</td><td><span :class="['badge', statusTone(item.status)]">{{ statusLabel[item.status] }}</span><small v-if="item.total_steps">第 {{ item.current_step }}/{{ item.total_steps }} 级</small></td><td class="approval-comment">{{ item.additional_approver_name || item.delegated_to_name || item.reviewer_name || '等待处理' }}<small>{{ item.additional_approver_name ? '已加签给 ' + item.additional_approver_name : item.delegated_to_name ? '已转签给 ' + item.delegated_to_name : item.comment }}</small></td><td><div v-if="item.status === 'pending' && user.role !== 'sales' && (!item.current_approver_ids?.length ? (!item.current_approver_roles?.length || item.current_approver_roles.includes(user.role)) : item.current_approver_ids.includes(user.id))" class="row-actions"><button class="text-button green-text" @click="review(item, 'approved')"><Check :size="14"/>通过</button><button class="text-button danger" @click="review(item, 'rejected')"><X :size="14"/>驳回</button><button class="text-button muted" @click="review(item, 'transferred')">转签</button><button class="text-button muted" @click="review(item, 'added')">加签</button></div><span v-else class="subtle">—</span></td></tr></tbody></table></div></section>
    <div v-if="selected" class="modal-backdrop" @click.self="!busy && (selected = undefined)"><section class="modal narrow" role="dialog" aria-modal="true" aria-label="处理审批"><header class="modal-header"><h2>{{ decision === 'approved' ? '通过审批' : decision === 'rejected' ? '驳回审批' : decision === 'transferred' ? '转签审批' : '加签审批' }}</h2><button class="icon-button" aria-label="关闭审批" @click="selected = undefined"><X :size="20"/></button></header><form @submit.prevent="submit"><div class="modal-body"><p>{{ selected.name }}</p><label v-if="decision === 'transferred' || decision === 'added'" class="field"><span>{{ decision === 'transferred' ? '转签给' : '加签给' }}</span><select v-model="transferTo" required><option value="" disabled>选择管理员或经理</option><option v-for="member in users.filter(member => member.id !== user.id && member.active && ['admin', 'manager'].includes(member.role) && member.organization_id === user.organization_id)" :key="member.id" :value="member.id">{{ member.name }}（{{ member.role === 'admin' ? '管理员' : '经理' }}）</option></select></label><label class="field"><span>{{ decision === 'transferred' ? '转签说明' : decision === 'added' ? '加签说明' : '审批意见' }}{{ decision === 'rejected' ? '（必填）' : '' }}</span><textarea v-model="comment" :required="decision === 'rejected'" maxlength="2000" rows="4" placeholder="请填写处理意见"/></label><p v-if="error" class="error-banner">{{ error }}</p></div><footer class="modal-footer"><button class="button" type="button" :disabled="busy" @click="selected = undefined">取消</button><button class="button primary" :disabled="busy">{{ busy ? '处理中…' : '确认' }}</button></footer></form></section></div>
  </div>
</template>
